using Azure.Identity;
using Azure.Extensions.AspNetCore.Configuration.Secrets;

var builder = WebApplication.CreateBuilder(args);

// In production, overlay secrets from Azure Key Vault
if (builder.Environment.IsProduction())
{
    var keyVaultUri = new Uri(builder.Configuration["KeyVault:VaultUri"]!);

    // Authenticate using Managed Identity without any hardcoded credentials
    builder.Configuration.AddAzureKeyVault(
        keyVaultUri,
        new DefaultAzureCredential(),
        new AzureKeyVaultConfigurationOptions
        {
            ReloadInterval = TimeSpan.FromHours(4) // Automatically refresh rotated secrets
        });
}

// Secrets from Key Vault are accessible via standard IConfiguration
var externalApiKey = builder.Configuration["ThirdPartyAiService:ApiKey"];
